"""Build the standard lesson mission; run with Python 3, no dependencies."""
from pathlib import Path
import json

ROOT = Path(__file__).resolve().parent.parent
steps = []
CSS = '''body{font:19px/1.65 Arial,sans-serif;color:#20354c;background:#fff;margin:0;padding:24px;max-width:920px;box-sizing:border-box}p{margin:15px 0}h3{font-size:23px;color:#165c83;margin:24px 0 10px}strong{color:#165c83}li{margin:8px 0}figure{margin:20px 0;padding:18px;border:1px solid #dce7f2;border-radius:16px;background:#f4f8fc;text-align:center}figure img{display:block;max-width:100%;width:auto;height:auto;max-height:290px;margin:auto}figcaption{font-size:14px;line-height:1.45;color:#52687d;margin-top:12px}.logos{display:flex;flex-wrap:wrap;gap:14px;justify-content:center}.logos figure{flex:1 1 160px;margin:0;min-width:0}.logos img{height:92px;max-width:150px;object-fit:contain}.example{background:#fff5df;border-left:5px solid #e7ad42;border-radius:8px;padding:15px 19px;margin:18px 0}.key{background:#e9f6ef;border-left:5px solid #38a57a;padding:15px 19px;border-radius:8px}.flow{background:#eaf2fc;padding:15px;border-radius:10px;text-align:center;font-weight:bold;color:#165c83}table{width:100%;border-collapse:collapse;font-size:17px}td,th{border:1px solid #ccdcea;padding:11px;text-align:left;vertical-align:top}th{background:#eaf2fc}table.systems{table-layout:fixed}table.systems th:first-child{width:24%}a{color:#126797}code{background:#edf2f7;border-radius:4px;padding:2px 5px;overflow-wrap:anywhere} @media(max-width:550px){body{padding:14px}td,th{padding:7px;font-size:16px}}'''
ASSETS = {
 'windows':('https://upload.wikimedia.org/wikipedia/commons/8/87/Windows_logo_-_2021.svg','Windows',''),
 'linux':('https://upload.wikimedia.org/wikipedia/commons/3/35/Tux.svg','Tux — символът на Linux','Larry Ewing и The GIMP · <a href="https://commons.wikimedia.org/wiki/File:Tux.svg">източник</a>'),
 'android':('https://upload.wikimedia.org/wikipedia/commons/3/31/Android_robot_head.svg','Android',''),
 'macos':('https://upload.wikimedia.org/wikipedia/commons/2/21/MacOS_wordmark_%282017%29.svg','macOS',''),
 'placement':('https://upload.wikimedia.org/wikipedia/commons/e/e1/Operating_system_placement.svg','Потребител → приложения → операционна система → хардуер','Golftheman · <a href="https://commons.wikimedia.org/wiki/File:Operating_system_placement.svg">източник</a> · <a href="https://creativecommons.org/licenses/by-sa/3.0/">CC BY-SA 3.0</a>'),
 'kernel':('https://upload.wikimedia.org/wikipedia/commons/8/8f/Kernel_Layout.svg','Applications = приложения; Kernel = ядро; CPU = процесор; Memory = памет; Devices = устройства.','Bobbo · <a href="https://commons.wikimedia.org/wiki/File:Kernel_Layout.svg">източник</a> · <a href="https://creativecommons.org/licenses/by-sa/3.0/">CC BY-SA 3.0</a>'),
 'office':('https://upload.wikimedia.org/wikipedia/commons/c/c0/LibreOffice_logo.svg','LibreOffice — пример за пакет от приложни програми.',''),
 'bash':('https://upload.wikimedia.org/wikipedia/commons/8/82/Gnu-bash-logo.svg','Bash — пример за командна обвивка.','Free Software Foundation · <a href="https://commons.wikimedia.org/wiki/File:Gnu-bash-logo.svg">източник</a> · <a href="https://artlibre.org/licence/lal/en/">Free Art License</a>')
}
def picture(key):
    url,caption,credit=ASSETS[key]
    return f'<figure><img src="{url}" alt="{caption}"><figcaption>{caption}'+(' <br>'+credit if credit else '')+'</figcaption></figure>'
def logos(keys=('windows','linux','macos')):return '<div class="logos">'+''.join(picture(k) for k in keys)+'</div>'
def wrap(body):return '<!doctype html><html lang="bg"><head><meta charset="utf-8"><style>'+CSS+'</style></head><body>'+body+'</body></html>'
def info(id,title,body):steps.append({'id':id,'step_content':{'type':'information','title':title,'instruction':wrap(body),'instruction_format':'html'},'step_rules':{}})
def choice(id,q,options,correct,feedback):
    assert len(options)==6 and 1<len(correct)<6
    steps.append({'id':id,'step_content':{'type':'multiple_choice','title':'Провери разбирането си','instruction':wrap('<p>'+q+'</p><p><strong>Избери всички верни отговори.</strong></p>'),'instruction_format':'html','options':[{'id':str(i+1),'text':v} for i,v in enumerate(options)],'correct_option_ids':[str(i+1) for i in correct],'feedback':feedback},'step_rules':{'automatic_feedback':True}})

info('intro','За какво е този урок?',logos()+'''<p>Когато включиш компютъра, отвориш програма или запишеш файл, зад тези действия стои <strong>Операционната система</strong>. Тя помага на програмите, устройствата и потребителя да работят заедно.</p><ul><li>Ще различаваш <strong>системен и приложен софтуер</strong>.</li><li>Ще разбираш какво правят <strong>операционната система, ядрото и обвивката</strong>.</li><li>Ще разпознаваш Windows, Linux и macOS и ще обясняваш защо съвместимостта е важна.</li><li>Ще проучиш историята на Windows и ще я представиш със свои думи.</li></ul>''')

info('os-definition','Какво е операционна система?','''<p><strong>Операционната система (ОС) е основният софтуер, който управлява компютъра, осигурява работата на програмите и позволява на потребителя да общува с него.</strong></p><p>Тя управлява процесора, паметта, файловете и устройствата и предоставя <strong>потребителски интерфейс</strong> — например прозорци, икони, менюта и бутони.</p><p>Примери за операционни системи са <strong>Windows, macOS и Android</strong></p>'''+picture('windows'))

info('software','Компютърен софтуер',picture('placement')+'''<p><strong>Компютърната система</strong> включва хардуер, софтуер и хората, които работят с тях. Хардуерът са физическите части — например процесор, памет и екран. <strong>Компютърният софтуер</strong> е съвкупността от програми, чрез които данните се обработват, съхраняват и показват.</p><p>Според предназначението си софтуерът се разделя на <strong>системен</strong> и <strong>приложен</strong>. Системният управлява хардуера и създава условия за работа на останалите програми. Приложният помага на потребителя да изпълни конкретна задача.</p><div class="example">Пишеш доклад в Word. <strong>Word е приложен софтуер</strong>, а <strong>Windows е системен софтуер</strong>. Клавиатурата, с която пишеш, е хардуер, а ти си потребителят.</div>''')
choice('software-check','Кои твърдения за компютърната система са верни?',['Клавиатурата е част от хардуера.','Word е операционна система.','Софтуерът включва програмите.','Потребителят също участва в компютърната система.','Всеки софтуер има едно и също предназначение.','Windows е приложна програма за писане на доклади.'],[0,2,3],'Хардуерът е физическата част, софтуерът са програмите, а човекът е потребител. Word е приложен софтуер, а Windows — системен.')

info('system-software','Системен софтуер и стартиране на компютъра',picture('windows')+'''<p><strong>Системният софтуер</strong> управлява компютърния хардуер и осигурява среда за приложенията. </p><p>Примери за <strong>системен софтуер</strong> (системни програми) са:</p><ol><li><strong>Microsoft Windows</strong> — операционна система.</li><li><strong>macOS</strong> — операционната система за компютри Mac.</li><li><strong>Ubuntu</strong> — операционна система, изградена с ядрото Linux.</li><li><strong>BIOS</strong> — вградена програма за подготовка и стартиране на компютъра.</li><li><strong>UEFI</strong> — съвременният заместник на BIOS.</li><li><strong>Драйвер за видеокарта</strong> — помага на операционната система да управлява видеокартата.</li><li><strong>Драйвер за звукова карта</strong> — помага на операционната система да работи със звуковото устройство.</li><li><strong>Драйвер за принтер</strong> — осигурява взаимодействието на операционната система с принтера.</li><li><strong>Windows Boot Manager</strong> — участва в стартирането на зареждането на Windows.</li><li><strong>Bash</strong> — командна обвивка, чрез която задаваме текстови команди.</li></ol><h3>Какво е BIOS?</h3><p><strong>BIOS</strong> означава <strong>Basic Input/Output System</strong> — „базова входно-изходна система“. Това е вградена програма, която се изпълнява при включване на компютъра, проверява и подготвя основните устройства и участва в стартирането на зареждането на операционната система.</p><h3>Какво е UEFI?</h3><p><strong>UEFI</strong> означава <strong>Unified Extensible Firmware Interface</strong> — „унифициран разширяем интерфейс на фърмуера“. <strong>Фърмуер</strong> наричаме вградения софтуер на устройство. За този урок можем да си представим UEFI като съвременния заместник на BIOS: той подготвя компютъра за работа при включване и стартира зареждането на операционната система.</p><p><strong>Микропрограмите на устройствата</strong> също са вграден софтуер, който управлява работата на отделни устройства.</p><div class="flow">Включване → BIOS/UEFI → зареждане на операционната система → работа с приложения</div><p>След зареждането си операционната система управлява текущата работа. Например Windows създава условия текстовият редактор да използва клавиатурата, паметта и запомнящото устройство. <strong>BIOS/UEFI и операционната система имат различни роли</strong>: първото подготвя стартирането, а операционната система организира работата след него.</p>''')
choice('system-check','Кои описания на системния софтуер са верни?',['BIOS/UEFI участва в стартирането преди зареждането на операционната система.','Windows е част от системния софтуер.','BIOS е текстов редактор за доклади.','Микропрограмите са вграден софтуер на устройства.','Операционната система има същата задача като компютърна игра.','Приложенията трябва да се стартират преди BIOS/UEFI.'],[0,1,3],'BIOS/UEFI подготвя стартирането, микропрограмите обслужват устройства, а операционната система осигурява средата за текущата работа. Игрите и редакторите са приложения.')

info('applications','Приложен софтуер и програмни пакети',picture('office')+'''<p><strong>Приложният софтуер</strong> включва програми за конкретни потребителски задачи: писане, рисуване, пресмятане, общуване или забавление. Отделната програма се разпространява като <strong>програмен продукт</strong>.</p><div class="key"><h3>Каква е разликата?</h3><p><strong><u>Приложният софтуер</u></strong> помага на потребителя да изпълни конкретна задача — например да напише текст в Word или да нарисува картина.</p><p><strong><u>Системният софтуер</u></strong> управлява хардуера и осигурява условията, в които приложенията работят. Например Windows организира използването на паметта и записването на файлове.</p><p><strong>Когато пишеш в Word, приложението ти помага да създадеш документа, а операционната система Windows осигурява работата му с компютъра.</strong></p></div><p><strong>Програмен пакет</strong> е обединение от няколко програмни продукта. Например Microsoft Office включва Word за текстове, Excel за електронни таблици и PowerPoint за презентации. В LibreOffice подобни задачи изпълняват Writer, Calc и Impress.</p><div class="example">За училищно събитие пишеш покана в Word, изчисляваш разходите в Excel и представяш идеята с PowerPoint. Използваш <strong>три различни приложения от един пакет</strong>.</div><p>Пакетът улеснява работата с няколко свързани задачи. Той не е операционна система: приложенията му се изпълняват в средата, която операционната система осигурява.</p>''')
choice('applications-check','Кои твърдения за приложенията и пакетите са верни?',['Word е отделен програмен продукт.','Microsoft Office е операционна система.','Един пакет може да съдържа няколко приложения.','Excel служи за електронни таблици.','Всички програми в един пакет изпълняват една и съща задача.','LibreOffice е физическа част на компютъра.'],[0,2,3],'Програмният пакет обединява отделни продукти с различни задачи. Word, Excel и PowerPoint са приложения, а не операционни системи или хардуер.')

info('interface','Потребителски интерфейс','''<p><strong>Една от основните функции на операционната система е да осигури потребителски интерфейс.</strong> Чрез него задаваме действия и получаваме резултати от компютъра.</p>'''+picture('bash')+'''<p><strong>Потребителски интерфейс</strong> са средствата и правилата, чрез които човекът общува с компютърната система. Когато натискаш бутон, избираш меню или въвеждаш команда, използваш интерфейс.</p><p>При <strong>графичния интерфейс</strong> работиш с прозорци, икони, менюта и бутони. Например отваряш папка с двойно щракване. При <strong>буквено-цифровия, или командния интерфейс</strong> въвеждаш текстови команди. Bash е пример за програма, която предоставя командна обвивка.</p><p>Потребителят работи с приложенията и със системния софтуер. Приложението отправя заявки към операционната система, а тя организира необходимата работа с хардуера.</p><div class="example">Избираш „Запиши“ в редактора. Бутонът е част от интерфейса на приложението. Редакторът заявява запис, а операционната система управлява записването на файла върху устройството.</div>''')
choice('interface-check','Кои примери описват правилно интерфейса?',['Избирането на бутон с мишката е работа с графичен интерфейс.','Интерфейсът е само външният вид на компютърния корпус.','Въвеждането на текстова команда е работа с команден интерфейс.','При запис редакторът използва услугите на операционната система.','Всяка икона е отделна физическа част на процесора.','Командният интерфейс изисква непременно щракване върху икони.'],[0,2,3],'Прозорците и бутоните са графичен интерфейс, а текстовите команди — команден. операционната система предоставя услуги на приложенията, включително за запис на файлове.')

info('application-types','Видове приложен софтуер',picture('office')+'''<p>Приложенията могат да се групират според задачите, които изпълняват. В учебника са разграничени <strong>четири групи</strong>. Така по-лесно избираме подходяща програма за конкретна работа.</p><table><tr><th>Вид</th><th>За какво служи?</th><th>Пример</th></tr><tr><td>С общо предназначение</td><td>За често срещани задачи</td><td>Текстообработка, таблици, презентации, рисуване, уеб браузър</td></tr><tr><td>С развлекателно предназначение</td><td>За забавление и възпроизвеждане на медии</td><td>Игра, медиен плейър</td></tr><tr><td>Със специално предназначение</td><td>За специализирани информационни задачи</td><td>Експертна система, транслатор, електронен речник, система за управление на съдържание</td></tr><tr><td>Професионални</td><td>За работа в конкретна професионална област</td><td>Инженерно проектиране, книгоиздаване, географски информационни системи</td></tr></table><p><strong>Транслаторът</strong> преобразува програмен код; <strong>експертната система</strong> използва знания и правила от определена област. <strong>Система за управление на съдържание</strong> помага за поддържане на сайт. Избираме приложението според нужната задача: за чертеж на сграда е подходяща професионална програма за проектиране.</p>''')
choice('types-check','Кои съответствия между задача и вид приложен софтуер са верни?',['Текстов редактор — програма с общо предназначение.','Компютърна игра — системен софтуер.','Електронен речник — програма със специално предназначение.','Инженерно проектиране — професионален софтуер.','BIOS — програма с развлекателно предназначение.','Медиен плейър — хардуерно устройство.'],[0,2,3],'Редакторът обслужва обща задача, речникът е специализиран информационен инструмент, а инженерната програма е за професионална област. Играта и плейърът са развлекателни приложения.')

info('os-choice','Операционна система: предназначение и избор',logos()+'''<p><strong>Операционната система (ОС)</strong> е съвкупност от програми за управление на компютърната система и за връзка с потребителя. Тя осигурява условия за работа на приложния и останалия системен софтуер.</p><p>Избираме операционна система според задачите си и <strong>хардуерните изисквания</strong>. Това са условията към процесора, RAM, свободното място и други компоненти. Компютърът трябва да ги изпълнява, за да работи избраната версия на операционната система.</p><p>Проверяваме и <strong>съвместимостта на приложението с операционната система</strong>. Програма, създадена за една система, може да изисква друга версия за работа в друга система.</p><div class="example">Имаш инсталатор на учебна програма за Windows. За компютър с macOS първо проверяваш дали разработчикът предлага версия за macOS. Самото копиране на Windows инсталатора не гарантира, че програмата ще работи.</div>''')
choice('compatibility-check','Кои действия са подходящи при избор на операционната система и приложения?',['Да проверя изискванията към RAM и процесора.','Да приема, че всяка програма работи с всяка операционна система.','Да потърся версия на приложението за моята операционната система.','Да избера операционната система според задачите и хардуера си.','Да съдя за съвместимостта само по красивото лого.','Да приема, че копирането на инсталатора гарантира работа на друга операционна система.'],[0,2,3],'Изборът зависи от задачата, хардуерните изисквания и наличната съвместима версия на приложението. Логото и копирането на файл не доказват съвместимост.')

info('os-functions','Основни функции на операционната система',picture('kernel')+'''<p>Операционната система върши много дейности, които често остават незабелязани. Можем да ги подредим в <strong>четири групи</strong>.</p><h3>Управление на програмите и процесите</h3><p><strong>Процес</strong> е изпълняваща се програма, която ползва ресурси на компютърната система. Програмата, наречена Операционна система, организира работата на процесите и им осигурява необходимите им ресурси, като памет, процесорно време, достъп до файлова система и периферни устройства.</p><h3>Потребителски интерфейс</h3><p>Предоставя средства за управление — например прозорци, менюта и команди.</p><h3>Файлова система</h3><p>Организира съхраняването и достъпа до файлове и папки върху запомнящите устройства.</p><h3>Системни функции</h3><p>Осигурява <strong>работа на няколко програми едновременно</strong> за потребителя, работа в мрежа и обмен на информация между периферните устройства и паметта.</p><div class="example">Докато пишеш документ, слушаш музика и изтегляш изображение. операционната система разпределя ресурсите, поддържа мрежовата връзка и организира записването на изтегления файл.</div>''')
choice('functions-check','Кои дейности са функции на операционната система?',['Да организира изпълнението на процесите.','Да поддържа файлове и папки върху запомнящите устройства.','Да замества физически RAM чиповете.','Да осигурява работа в мрежа.','Да пише самостоятелно съдържанието на всеки ученически доклад.','Да премахва нуждата от хардуер.'],[0,1,3],'Операционната система управлява процеси, файлове, памет и устройства и осигурява мрежова работа. Хардуерът остава необходим, а съдържанието на доклада се създава от потребителя.')

info('subsystems','Управление на процеси, файлове и команди','''<p><strong>Файлът е съвкупност от данни, записани под определено име на запомнящо устройство</strong> — например SSD, твърд диск или флаш памет. Един файл може да съдържа текст, снимка, музика, видео или програма.</p><div class="example">Когато напишеш доклад и го запишеш като <strong>Доклад.docx</strong>, създаваш файл. Снимката <strong>Екскурзия.jpg</strong> е друг файл. Файловете се подреждат в <strong>папки</strong>, за да ги намираме по-лесно.</div>'''+picture('bash')+'''<p>Зад основните функции стоят свързани части на системата. Учебният модел разглежда <strong>управление на процесите</strong>, <strong>управление на файловете</strong> и <strong>интерпретиране на команди</strong>.</p><ul><li>Управлението на процесите организира изпълнението на работещите програми и разпределя ресурси.</li><li>Управлението на файловете осигурява действия като създаване, четене, записване и намиране на файлове.</li><li><strong>Командният интерпретатор</strong> приема въведена команда, разчита я и организира изпълнението ѝ.</li></ul><div class="example">В команден прозорец на Windows командата <code>dir</code> показва съдържанието на текущата папка. Командният интерпретатор разчита командата, а файловата система предоставя информацията за файловете.</div><p>Това са различни роли, които си сътрудничат. Командният интерпретатор не е програма за писане на доклад и не е самото устройство за съхранение. <strong>Командният интерпретатор е програма, която приема написаните от потребителя команди, разчита ги и организира изпълнението им.</strong> <strong>Командният интерпретатор е системна програма, която обикновено е част от операционната система.</strong> Той е вид <strong>обвивка</strong>, чрез която потребителят задава текстови команди.</p>''')
choice('subsystems-check','Кои роли са описани правилно?',['Управлението на процесите организира работата на изпълняващите се програми.','Командният интерпретатор е твърдият диск.','Управлението на файловете участва в четенето и записването им.','Командният интерпретатор разчита въведени команди.','Файловата система определя какъв текст ще напише ученикът.','Управлението на процесите означава само избор на фон за екрана.'],[0,2,3],'Процесите са изпълняващите се програми; файловото управление обслужва данните във файлове; интерпретаторът разчита командите. Това са софтуерни роли.')

info('kernel-shell','Ядро и обвивка',picture('kernel')+'''<p><strong>Ядрото</strong> е основната част на операционната система. При стартиране то се зарежда в паметта и участва в управлението на процесора, паметта и устройствата. Приложенията използват услугите му, за да работят с ресурсите на компютъра.</p><p><strong>Обвивката</strong> осъществява връзката с потребителя и предоставя начин за подаване на команди. Командна обвивка е например Bash. Графичната среда позволява да управляваме чрез прозорци, менюта и икони.</p><div class="example">Въвеждаш команда за показване на файловете в папка. Обвивката приема и разчита командата. За необходимите операции се използват услугите на операционната система и нейното ядро. Резултатът се представя на екрана.</div><div class="key"><strong>Запомни:</strong> обвивката помага да зададеш действието, а ядрото управлява основните ресурси, необходими за изпълнението му.</div>''')
steps.append({'id':'kernel-ai','step_content':{'type':'open_answer','title':'Обясни със свои думи','instruction':wrap('<p>Как си сътрудничат обвивката и ядрото, когато зададеш команда за показване на файловете в папка?</p>'),'instruction_format':'html','reference_answer':'Обвивката приема и разчита командата ми за показване на файловете. Тя използва услугите на операционната система, чието ядро управлява необходимите ресурси и достъпа до устройствата. Информацията за файловете се получава и резултатът се показва на екрана.'},'step_rules':{'ai_feedback':True,'automatic_feedback':False,'send_progress':True}})

info('os-examples','Windows, Linux, macOS и Android',logos(('windows','linux','macos','android'))+'''<p>Различните операционни системи имат сходни основни задачи, но различни интерфейси, приложения и хардуерни изисквания.</p><table class="systems"><tr><th>Система</th><th>Какво е характерно?</th></tr><tr><td><strong>Microsoft Windows</strong></td><td>Разработва се от Microsoft. Използва се на компютри от различни производители и предлага графичен интерфейс и много приложения.</td></tr><tr><td><strong>Linux</strong></td><td>Linux е ядро с отворен код. Върху него са изградени завършени системи, наречени дистрибуции — например Ubuntu. Много от тях могат да се използват безплатно.</td></tr><tr><td><strong>macOS</strong></td><td>Разработва се от Apple за компютрите Mac. Съчетава графичен интерфейс със собствени системни инструменти и съвместими приложения.</td></tr><tr><td><strong>Android</strong></td><td>Операционна система, използвана в много смартфони и таблети. Изградена е върху ядрото Linux. Осигурява работа с приложения и управление чрез сензорен екран — например докосване на икона, за да отвориш приложение.</td></tr></table><p><strong>Отворен код</strong> означава, че програмният код е достъпен и може да се изучава, променя и разпространява при условията на лиценза.</p><div class="example">И в Windows, и в macOS можеш да работиш с файлове, да стартираш приложения и да използваш мрежа. Разликите са в конкретните средства и съвместимите версии на програмите.</div><p>За сравнение на две операционни системи използвай едни и същи показатели: предназначение, интерфейс, хардуер и приложения.</p>''')
choice('examples-check','Кои твърдения за системите са верни?',['macOS се разработва от Apple за компютри Mac.','Linux е единствената съществувала някога безплатна операционна система.','Ubuntu е пример за дистрибуция, използваща Linux.','Android се използва в много смартфони и таблети и е изграден върху ядрото Linux.','Отворен код означава, че програмата няма никакви лицензионни условия.','Windows и macOS имат функции за работа с файлове и приложения.'],[0,2,3,5],'macOS е системата на Apple за Mac. Linux е основата на дистрибуции като Ubuntu и се използва като ядро и в Android. Android работи в много смартфони и таблети. Windows и macOS имат функции за работа с файлове и приложения. Отвореният код се използва при условията на съответния лиценз.')

info('windows-history','Практическа работа: кратка история на Windows',picture('windows')+'''<p>Проучи накратко историята на <strong>Microsoft Windows</strong>. Използвай страниците на български и проследи три важни момента от развитието на системата.</p><h3>Източници на български</h3><ul><li><a href="https://bg.wikipedia.org/wiki/Microsoft_Windows">Microsoft Windows — общ преглед и история</a></li><li><a href="https://bg.wikipedia.org/wiki/Windows_95">Windows 95</a></li><li><a href="https://bg.wikipedia.org/wiki/Windows_11">Windows 11</a></li></ul><h3>Три опорни момента</h3><ul><li><strong>1985 г. — Windows 1.0.</strong> Microsoft предлага графична среда за работа върху MS-DOS, с прозорци и работа с мишка.</li><li><strong>1995 г. — Windows 95.</strong> Появяват се менюто „Старт“ и лентата на задачите, които улесняват отварянето и превключването между програми.</li><li><strong>2021 г. — Windows 11.</strong> Излиза нова версия с обновен графичен интерфейс и променен облик на менюто „Старт“.</li></ul><p>Отвори връзките и намери информацията за тези версии. За по-бързо търсене в страницата натисни <strong>Ctrl + F</strong> и въведи например <strong>1985</strong> или <strong>Старт</strong>.</p><div class="key">В следващата стъпка напиши <strong>един кратък абзац със свои думи</strong>, който проследява тези три момента. Включи годините, версиите и посочените промени.</div>''')
steps.append({'id':'windows-history-answer','step_content':{'type':'open_answer','title':'Разкажи накратко историята на Windows','instruction':wrap('<p>Как се развива Windows от Windows 1.0 през Windows 95 до Windows 11?</p><p>Отговори със свои думи в кратък абзац, като използваш трите опорни момента от предишната стъпка.</p>'),'instruction_format':'html','reference_answer':'Историята на Windows започва през 1985 г. с Windows 1.0 — графична среда върху MS-DOS с прозорци и работа с мишка. През 1995 г. Windows 95 въвежда менюто „Старт“ и лентата на задачите, които улесняват работата с програмите. През 2021 г. излиза Windows 11 с обновен графичен интерфейс и променен облик на менюто „Старт“.'},'step_rules':{'send_progress':True,'automatic_feedback':True,'ai_feedback':False}})

info('summary','Най-важното от урока',logos()+'''<ul><li><strong>Системният софтуер</strong> управлява хардуера и осигурява условия за приложенията; <strong>приложният</strong> изпълнява потребителски задачи.</li><li><strong>Операционната система</strong> управлява процеси, файлове, ресурси, мрежова работа и взаимодействието с потребителя.</li><li>Обвивката на операционната система приема действията, а ядрото управлява основните ресурси.</li><li><strong>Windows, системите с Linux и macOS</strong> имат сходни основни функции, но различни приложения и изисквания.</li></ul>''')

